#!/usr/bin/env bash
# Proof-IDENTITY oracle for the trajectory-preserving V6 Congruence cost work
# (see cong-index-2026-08-04.sh for what changed). Emits the DRAT proof to
# node-local scratch and prints its size + md5 alongside the trajectory stats.
# A speedup that moves ONE byte of this proof is a trajectory fork, i.e. a
# failure — the TB4b precedent (byte-identical DRAT totals) is the bar.
#
# DO NOT EDIT THIS FILE WHILE JOBS RUN IT: bash reads a script incrementally, so
# an in-place edit truncates the tail of a running instance (that is exactly how
# the first Tier C round lost its md5 lines).
#
# usage: cong-proofid-2026-08-04.sh <base|opt> <tier> <instance-prefix> <cap-sec>
set -u
R=$(git -C "$(dirname "$(realpath "$0")")" rev-parse --show-toplevel)
arm="$1"; tier="$2"; inst="$3"; cap="$4"
bin="$R/build/pin-cong-$arm/tactix"
f=$(ls "$R/benchmarks/cache/$tier/${inst}"*.cnf.xz | head -1)
cnf="$TMPDIR/congid.$SLURM_JOB_ID.cnf"
prf="$TMPDIR/congid.$SLURM_JOB_ID.drat"
xz -dc "$f" > "$cnf"
echo "=== arm=$arm tier=$tier inst=$inst bin=$bin ==="
/usr/bin/time -f "wall %e" timeout "$cap" "$bin" "$cnf" "$prf" 2>&1 |
  grep -E "^s |^wall |^c conflicts|^c congruence|^c conggates|^c timing +[0-9]|Congruence"
ls -l "$prf" || echo "NO PROOF FILE"
echo "proof-bytes $(stat -c %s "$prf" 2>&1)"
echo "proof-md5   $(md5sum "$prf" 2>&1 | cut -d' ' -f1)"
rm -f "$cnf" "$prf"
echo "=== done arm=$arm inst=$inst ==="
